//! HTTP клиент для внешних API
//!
//! Предоставляет типизированный интерфейс для взаимодействия с внешними сервисами.
//! Включает автоматические повторы, валидацию и логирование запросов.

// === IMPORTS ===
use std::time::Duration;

// === CONSTANTS ===
// Глобальные настройки HTTP клиента
//
// Определяют поведение по умолчанию для всех HTTP запросов,
// включая таймауты и количество попыток при сбоях.
lazy_static! {
    static ref DEFAULT_CONFIG: HttpConfig = {
        HttpConfig::new()
            .with_timeout(Duration::from_secs(30))
            .with_retries(3)
    };
}

// === STRUCTS ===
/// Конфигурация HTTP клиента
///
/// Содержит настройки для создания HTTP клиентов с единообразным
/// поведением во всем приложении.
pub struct HttpConfig {
    /// Таймаут для запросов
    timeout: Duration,
    /// Количество повторов при сбоях
    retries: u32,
}

